  "kind" text,  -- one of: foto | taller | privada | rodaje | popup
  "client_name" text,  -- PII · Ley 1581
  "contact" text,  -- PII · Ley 1581
  "starts_at" timestamptz,
  "ends_at" timestamptz,
  "quoted" bigint,
  "status" text,  -- one of: enquiry | quoted | confirmed | completed | lost
  "created_at" timestamptz default now(),
  "updated_at" timestamptz default now()
);
alter table public.space_rentals drop constraint if exists space_rentals_kind_check;
alter table public.space_rentals add constraint space_rentals_kind_check
  check ("kind" is null or "kind" in ('foto', 'taller', 'privada', 'rodaje', 'popup'));
alter table public.space_rentals drop constraint if exists space_rentals_status_check;
alter table public.space_rentals add constraint space_rentals_status_check
  check ("status" is null or "status" in ('enquiry', 'quoted', 'confirmed', 'completed', 'lost'));
create index if not exists space_rentals_tenant_id_idx on public.space_rentals("tenant_id");
drop trigger if exists space_rentals_touch on public.space_rentals;
create trigger space_rentals_touch before update on public.space_rentals
  for each row execute function public.touch_updated_at();

-- -----------------------------------------------------------------------------
-- tasks  ·  Operations
-- The build kanban (K-01) and, later, studio operational tasks: opening checklist, maintenance.
-- -----------------------------------------------------------------------------
create table if not exists public.tasks (
  "id" uuid primary key default gen_random_uuid(),
  "tenant_id" uuid,
  "title" jsonb,
  "phase" text,
  "status" text,  -- one of: backlog | todo | doing | blocked | done
  "owner" text,
  "spec_codes" jsonb,
  "blocked_reason" text,
  "created_at" timestamptz default now(),
  "updated_at" timestamptz default now()
);
alter table public.tasks drop constraint if exists tasks_status_check;
alter table public.tasks add constraint tasks_status_check
  check ("status" is null or "status" in ('backlog', 'todo', 'doing', 'blocked', 'done'));
create index if not exists tasks_tenant_id_idx on public.tasks("tenant_id");
drop trigger if exists tasks_touch on public.tasks;
create trigger tasks_touch before update on public.tasks
  for each row execute function public.touch_updated_at();

-- -----------------------------------------------------------------------------
-- audit_log  ·  System & audit
-- Append-only. Records reads as well as writes on personal data, which Ley 1581 requires. Never editable, never deletable.
-- -----------------------------------------------------------------------------
create table if not exists public.audit_log (
  "id" uuid primary key default gen_random_uuid(),
  "tenant_id" uuid,
  "actor_id" uuid,
  "action" text,  -- one of: read | create | update | delete | login | export
  "entity" text,
  "entity_id" uuid,
  "before" jsonb,
  "after" jsonb,
  "ip_address" text,  -- PII · Ley 1581
  "user_agent" text,
  "created_at" timestamptz default now()
);
alter table public.audit_log drop constraint if exists audit_log_action_check;
alter table public.audit_log add constraint audit_log_action_check
  check ("action" is null or "action" in ('read', 'create', 'update', 'delete', 'login', 'export'));
create index if not exists audit_log_tenant_id_idx on public.audit_log("tenant_id");
create index if not exists audit_log_actor_id_idx on public.audit_log("actor_id");

-- -----------------------------------------------------------------------------
-- changelog_entries  ·  System & audit
-- Every prompt and every change to this system: intent, decision, alternative rejected, files touched, screenshots. Powers /docs.
-- -----------------------------------------------------------------------------
create table if not exists public.changelog_entries (
  "id" uuid primary key default gen_random_uuid(),
  "seq" integer unique,
  "date" date,
  "version" text,
  "author" text,
  "prompt" text,  -- the request, verbatim
  "intent" jsonb,
  "decisions" jsonb,
  "rejected" jsonb,
  "files" jsonb,
  "screenshots" jsonb,
  "spec_codes" jsonb,
  "created_at" timestamptz default now()
);

-- -----------------------------------------------------------------------------
-- integrations  ·  System & audit
-- Third parties and their credentials: Wompi, WhatsApp Cloud API, the email sender, DIAN, Supabase.
-- -----------------------------------------------------------------------------
create table if not exists public.integrations (
  "id" uuid primary key default gen_random_uuid(),
  "tenant_id" uuid,
  "provider" text,  -- one of: wompi | whatsapp_cloud | resend | dian | supabase | google_maps | liveblocks
  "environment" text,  -- one of: sandbox | production
  "config" jsonb,
  "secret_ref" text,  -- secret — never select in the client; a reference, never the secret itself
  "status" text,  -- one of: not_configured | connected | error
  "last_checked_at" timestamptz,
  "created_at" timestamptz default now(),
  "updated_at" timestamptz default now()
);
alter table public.integrations drop constraint if exists integrations_provider_check;
alter table public.integrations add constraint integrations_provider_check
  check ("provider" is null or "provider" in ('wompi', 'whatsapp_cloud', 'resend', 'dian', 'supabase', 'google_maps', 'liveblocks'));
alter table public.integrations drop constraint if exists integrations_environment_check;
alter table public.integrations add constraint integrations_environment_check
  check ("environment" is null or "environment" in ('sandbox', 'production'));
alter table public.integrations drop constraint if exists integrations_status_check;
alter table public.integrations add constraint integrations_status_check
  check ("status" is null or "status" in ('not_configured', 'connected', 'error'));
create index if not exists integrations_tenant_id_idx on public.integrations("tenant_id");
drop trigger if exists integrations_touch on public.integrations;
create trigger integrations_touch before update on public.integrations
  for each row execute function public.touch_updated_at();

-- -----------------------------------------------------------------------------
-- webhooks  ·  System & audit
-- Inbound events from Wompi and WhatsApp, stored raw before they are processed, so a failure can be replayed.
-- -----------------------------------------------------------------------------
create table if not exists public.webhooks (
  "id" uuid primary key default gen_random_uuid(),
  "tenant_id" uuid,
  "provider" text,
  "event" text,
  "payload" jsonb,
  "signature_valid" boolean,
  "processed_at" timestamptz,
  "error" text,
  "created_at" timestamptz default now()
);
create index if not exists webhooks_tenant_id_idx on public.webhooks("tenant_id");

-- -----------------------------------------------------------------------------
-- components  ·  System & audit
-- The living inventory (D-02). Every component in the system with its tier and states. No component exists in a screen without an entry here.
-- -----------------------------------------------------------------------------
create table if not exists public.components (
  "id" uuid primary key default gen_random_uuid(),
  "name" text unique,
  "tier" text,  -- one of: atom | molecule | organism | template | page
  "file" text,
  "states" jsonb,
  "used_by" jsonb,  -- spec codes
  "retired_at" timestamptz,
  "created_at" timestamptz default now(),
  "updated_at" timestamptz default now()
);
alter table public.components drop constraint if exists components_tier_check;
alter table public.components add constraint components_tier_check
  check ("tier" is null or "tier" in ('atom', 'molecule', 'organism', 'template', 'page'));
drop trigger if exists components_touch on public.components;
create trigger components_touch before update on public.components
  for each row execute function public.touch_updated_at();

