-- The role of the calling user, read from their profile.
create or replace function public.current_role_name() returns text
language sql stable security definer set search_path = public as $$
  select role from public.profiles where user_id = auth.uid() limit 1;
$$;

-- The tenant of the calling user. Every tenant-scoped policy funnels through
-- this, which is what makes multi-tenancy a property of the database rather
-- than a discipline the application has to remember.
create or replace function public.current_tenant_id() returns uuid
language sql stable security definer set search_path = public as $$
  select tenant_id from public.profiles where user_id = auth.uid() limit 1;
$$;

create or replace function public.has_permission(perm text) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.role_permissions
    where role = public.current_role_name() and permission = perm
  );
$$;

-- The profile id of the calling user, for "their own row" policies.
create or replace function public.current_profile_id() returns uuid
language sql stable security definer set search_path = public as $$
  select id from public.profiles where user_id = auth.uid() limit 1;
$$;

-- role_permissions lives in the public schema, so Supabase exposes it through
-- PostgREST like any other table. It is not secret — it is the same matrix the
-- client already ships in roles.js — but it must never be writable from a
-- client, or a student could grant themselves 'tables:write'. Readable to
-- signed-in users, written only by the service role (which bypasses RLS).
alter table public.role_permissions enable row level security;
drop policy if exists role_permissions_select on public.role_permissions;
create policy role_permissions_select on public.role_permissions
  for select to authenticated using (true);

-- =============================================================================
-- Row Level Security
--
-- Enabled on every table. A table with an empty `read` list in schema.js is
-- readable by any signed-in user of the tenant (the catalogue: classes, plans,
-- teachers). A table with permissions listed requires one of them.
-- =============================================================================

-- tenants
alter table public.tenants enable row level security;
drop policy if exists tenants_select on public.tenants;
drop policy if exists tenants_insert on public.tenants;
drop policy if exists tenants_update on public.tenants;
drop policy if exists tenants_delete on public.tenants;
create policy tenants_select on public.tenants for select
  using (true and (public.has_permission('tenant:manage')));
create policy tenants_insert on public.tenants for insert
  with check (true and (public.has_permission('tenant:manage')));
create policy tenants_update on public.tenants for update
  using (true and (public.has_permission('tenant:manage'))) with check (true);
create policy tenants_delete on public.tenants for delete
  using (true and (public.has_permission('tenant:manage')));

-- users
alter table public.users enable row level security;
drop policy if exists users_select on public.users;
drop policy if exists users_insert on public.users;
drop policy if exists users_update on public.users;
drop policy if exists users_delete on public.users;
create policy users_select on public.users for select
  using (tenant_id = public.current_tenant_id() and (public.has_permission('customer:read')));
create policy users_insert on public.users for insert
  with check (tenant_id = public.current_tenant_id() and (public.has_permission('staff:manage')));
create policy users_update on public.users for update
  using (tenant_id = public.current_tenant_id() and (public.has_permission('staff:manage'))) with check (tenant_id = public.current_tenant_id());
create policy users_delete on public.users for delete
  using (tenant_id = public.current_tenant_id() and (public.has_permission('staff:manage')));

