create policy integrations_select on public.integrations for select
  using (tenant_id = public.current_tenant_id() and (public.has_permission('settings:write')));
create policy integrations_insert on public.integrations for insert
  with check (tenant_id = public.current_tenant_id() and (public.has_permission('settings:write')));
create policy integrations_update on public.integrations for update
  using (tenant_id = public.current_tenant_id() and (public.has_permission('settings:write'))) with check (tenant_id = public.current_tenant_id());
create policy integrations_delete on public.integrations for delete
  using (tenant_id = public.current_tenant_id() and (public.has_permission('settings:write')));

-- webhooks
alter table public.webhooks enable row level security;
drop policy if exists webhooks_select on public.webhooks;
drop policy if exists webhooks_insert on public.webhooks;
drop policy if exists webhooks_update on public.webhooks;
drop policy if exists webhooks_delete on public.webhooks;
create policy webhooks_select on public.webhooks for select
  using (tenant_id = public.current_tenant_id() and (public.has_permission('audit:read')));
-- webhooks has no write permissions in schema.js: writes are service-role only.

-- components
alter table public.components enable row level security;
drop policy if exists components_select on public.components;
drop policy if exists components_insert on public.components;
drop policy if exists components_update on public.components;
drop policy if exists components_delete on public.components;
create policy components_select on public.components for select
  using (true and true);
create policy components_insert on public.components for insert
  with check (true and (public.has_permission('dev:inspect')));
create policy components_update on public.components for update
  using (true and (public.has_permission('dev:inspect'))) with check (true);
create policy components_delete on public.components for delete
  using (true and (public.has_permission('dev:inspect')));

